{
  "severity": "critical",
  "host_observations": [
    {"host": "DC-CORP-03.corp.local", "role": "production-dc", "user": "m.rashid", "first_seen": "2032-12-08T02:48:08+0000", "last_seen": "2032-12-08T02:53:00+0000"}
