  "attack_progression": [
    {"step": 1, "tactic": "DLL file staging in user Temp + System32 copy", "technique": "T1556.002", "what_happened": "At 2032-12-08 02:48:08 UTC on DC-CORP-03.corp.local, Sysmon EID 11 captured creation of C:\\Users\\m.rashid\\AppData\\Local\\Temp\\p139_pf_024808\\corp_passfilt.dll (232 bytes, MZ-PE header). At 02:48:14, Sysmon EID 11 ALSO recorded creation of C:\\Windows\\System32\\corp_passfilt.dll by powershell.exe (NOT TrustedInstaller). Rule 92201 triggered.", "chain_reason": "A new DLL written into C:\\Windows\\System32\\ by anything other than Microsoft TrustedInstaller / Windows Modules Installer is a high-fidelity tampering signal. The filename 'corp_passfilt.dll' matches the password-filter naming convention LSASS will accept."},
    {"step": 2, "tactic": "HKLM\\...\\Lsa\\Notification Packages REG_MULTI_SZ modification", "technique": "T1556.002", "what_happened": "At 2032-12-08 02:48:24, Sysmon EID 13 (Registry Value Set) recorded modification of HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages from previous value 'rassfm scecli' to NEW value 'rassfm scecli corp_passfilt' (REG_MULTI_SZ). Process powershell.exe. Rule 92213 triggered.", "chain_reason": "HKLM\\...\\Lsa\\Notification Packages is the registry value that LSASS reads at boot to load password-filter DLLs. Appending a new entry tells LSASS to load the named DLL and CALL its PasswordChangeNotify and PasswordFilter callbacks during EVERY password change AND EVERY domain authentication — exposing every cleartext password in the corp to the malicious DLL."},
    {"step": 3, "tactic": "Read of Authentication Packages + Security Packages (SSPI providers)", "technique": "T1556.002", "what_happened": "At 2032-12-08 02:48:38, AMSI EID 4104 captured Get-ItemProperty on HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Authentication Packages AND Security Packages. Both are SSPI provider lists — the attacker enumerated them to find other persistence-injection paths beyond Notification Packages.", "chain_reason": "Reading Authentication Packages and Security Packages is reconnaissance for related T1556 sub-vectors (custom SSPI provider, custom auth package). The attacker is mapping all LSASS-injection paths, not just the one they used."},
    {"step": 4, "tactic": "AMSI variant tool literals + reg add canonical syntax", "technique": "T1556.002", "what_happened": "AMSI EID 4104 captured scriptblock literals: 'reg add \"HKLM\\System\\CurrentControlSet\\Control\\Lsa\" /v \"Notification Packages\" /t REG_MULTI_SZ /d \"rassfm\\0scecli\\0evil\"', 'Mimilib.dll injection (mimikatz misc::regedit)', 'SecurityPackages override: New SSPI provider for backdoor auth', 'AuthLib P/Invoke: registering custom Negotiate provider'. Rule 92207 triggered (Sysmon EID 7 image load expected at next reboot).", "chain_reason": "Literal 'Mimilib.dll injection' OR 'reg add Notification Packages' with REG_MULTI_SZ payload in a PowerShell scriptblock has zero legitimate use. The persistence will fully activate at the next LSASS restart (DC reboot) when LSASS loads corp_passfilt.dll and starts intercepting every password change."}
  ],
  "time_window": {"start": "2032-12-08T02:48:08+0000", "end": "2032-12-08T02:53:00+0000"},
